CREATE TABLE "TB_FRED_SERIES" (
    "SERIES_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "SERIES_CD" VARCHAR(80) NOT NULL,
    "SERIES_NM" VARCHAR(300) NOT NULL,
    "CATEGORY_CD" VARCHAR(40) NOT NULL DEFAULT 'MACRO',
    "CNTRY_CD" VARCHAR(10) NOT NULL DEFAULT 'US',
    "FREQUENCY_CD" VARCHAR(20),
    "UNIT_NM" VARCHAR(300),
    "SEASONAL_ADJ_NM" VARCHAR(200),
    "OBS_START_DT" DATE,
    "OBS_END_DT" DATE,
    "FRED_LAST_UPD_DTTM" TIMESTAMPTZ,
    "TRANSFORM_CD" VARCHAR(10) NOT NULL DEFAULT 'lin',
    "AGGREGATION_CD" VARCHAR(10) NOT NULL DEFAULT 'avg',
    "COLLECT_CYCLE_CD" VARCHAR(20) NOT NULL DEFAULT 'DAILY',
    "REFRESH_OVERLAP_DAY" INTEGER NOT NULL DEFAULT 120,
    "VINTAGE_POLICY_CD" VARCHAR(30) NOT NULL DEFAULT 'LATEST_ONLY',
    "TARGET_CD" VARCHAR(80),
    "LAST_SUCCESS_DT" DATE,
    "LATEST_OBS_DT" DATE,
    "USE_YN" CHAR(1) NOT NULL DEFAULT 'Y',
    "CRT_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UPD_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "UK_TB_FRED_SERIES_01" UNIQUE ("SERIES_CD"),
    CONSTRAINT "CK_TB_FRED_SERIES_01" CHECK ("USE_YN" IN ('Y','N')),
    CONSTRAINT "CK_TB_FRED_SERIES_02" CHECK ("REFRESH_OVERLAP_DAY" BETWEEN 0 AND 3650),
    CONSTRAINT "CK_TB_FRED_SERIES_03" CHECK ("VINTAGE_POLICY_CD" IN ('LATEST_ONLY','REVISION_HISTORY'))
);

CREATE TABLE "TB_FRED_CLCT_JOB" (
    "JOB_ID" UUID PRIMARY KEY,
    "FROM_DT" DATE NOT NULL,
    "TO_DT" DATE NOT NULL,
    "STATUS" VARCHAR(30) NOT NULL,
    "SERIES_CDS" VARCHAR(4000) NOT NULL,
    "REQUEST_INTERVAL_MS" BIGINT NOT NULL DEFAULT 250,
    "TOTAL_ITEM_CNT" INTEGER NOT NULL DEFAULT 0,
    "SUCCESS_ITEM_CNT" INTEGER NOT NULL DEFAULT 0,
    "FAILED_ITEM_CNT" INTEGER NOT NULL DEFAULT 0,
    "PENDING_ITEM_CNT" INTEGER NOT NULL DEFAULT 0,
    "ERROR_MSG" VARCHAR(4000),
    "CRT_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "START_DTTM" TIMESTAMPTZ,
    "END_DTTM" TIMESTAMPTZ,
    CONSTRAINT "CK_TB_FRED_CLCT_JOB_01" CHECK ("FROM_DT" <= "TO_DT"),
    CONSTRAINT "CK_TB_FRED_CLCT_JOB_02" CHECK ("REQUEST_INTERVAL_MS" BETWEEN 0 AND 60000)
);

CREATE TABLE "TB_FRED_CLCT_JOB_ITEM" (
    "JOB_ITEM_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "JOB_ID" UUID NOT NULL REFERENCES "TB_FRED_CLCT_JOB"("JOB_ID") ON DELETE CASCADE,
    "SERIES_ID" BIGINT NOT NULL REFERENCES "TB_FRED_SERIES"("SERIES_ID"),
    "STATUS" VARCHAR(30) NOT NULL DEFAULT 'PENDING',
    "RECEIVED_CNT" INTEGER NOT NULL DEFAULT 0,
    "INSERTED_CNT" INTEGER NOT NULL DEFAULT 0,
    "UPDATED_CNT" INTEGER NOT NULL DEFAULT 0,
    "UNCHANGED_CNT" INTEGER NOT NULL DEFAULT 0,
    "MISSING_CNT" INTEGER NOT NULL DEFAULT 0,
    "REVISION_CNT" INTEGER NOT NULL DEFAULT 0,
    "ATTEMPT_CNT" INTEGER NOT NULL DEFAULT 0,
    "ERROR_MSG" VARCHAR(4000),
    "START_DTTM" TIMESTAMPTZ,
    "END_DTTM" TIMESTAMPTZ,
    CONSTRAINT "UK_TB_FRED_CLCT_JOB_ITEM_01" UNIQUE ("JOB_ID", "SERIES_ID")
);

CREATE TABLE "TB_FRED_OBS" (
    "FRED_OBS_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "SERIES_ID" BIGINT NOT NULL REFERENCES "TB_FRED_SERIES"("SERIES_ID"),
    "OBS_DT" DATE NOT NULL,
    "OBS_VAL" NUMERIC(30,10),
    "VALUE_STS_CD" VARCHAR(30) NOT NULL,
    "REALTIME_START_DT" DATE,
    "REALTIME_END_DT" DATE,
    "RAW_HASH" VARCHAR(64),
    "FIRST_JOB_ID" UUID REFERENCES "TB_FRED_CLCT_JOB"("JOB_ID"),
    "LAST_JOB_ID" UUID REFERENCES "TB_FRED_CLCT_JOB"("JOB_ID"),
    "FIRST_COLLECT_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "LAST_COLLECT_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "DATA_STS" VARCHAR(20) NOT NULL DEFAULT 'FRESH',
    CONSTRAINT "UK_TB_FRED_OBS_01" UNIQUE ("SERIES_ID", "OBS_DT"),
    CONSTRAINT "CK_TB_FRED_OBS_01" CHECK ("VALUE_STS_CD" IN ('VALUE','MISSING','REVISED'))
);

CREATE TABLE "TB_FRED_OBS_HIST" (
    "FRED_OBS_HIST_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "SERIES_ID" BIGINT NOT NULL REFERENCES "TB_FRED_SERIES"("SERIES_ID"),
    "OBS_DT" DATE NOT NULL,
    "REVISION_SEQ" INTEGER NOT NULL,
    "OLD_OBS_VAL" NUMERIC(30,10),
    "NEW_OBS_VAL" NUMERIC(30,10),
    "CHANGE_TYPE_CD" VARCHAR(30) NOT NULL,
    "REALTIME_START_DT" DATE,
    "REALTIME_END_DT" DATE,
    "JOB_ID" UUID REFERENCES "TB_FRED_CLCT_JOB"("JOB_ID"),
    "DETECTED_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "UK_TB_FRED_OBS_HIST_01" UNIQUE ("SERIES_ID", "OBS_DT", "REVISION_SEQ")
);

CREATE INDEX "IDX_TB_FRED_OBS_01" ON "TB_FRED_OBS"("SERIES_ID", "OBS_DT" DESC);
CREATE INDEX "IDX_TB_FRED_JOB_01" ON "TB_FRED_CLCT_JOB"("STATUS", "CRT_DTTM" DESC);
CREATE INDEX "IDX_TB_FRED_ITEM_01" ON "TB_FRED_CLCT_JOB_ITEM"("JOB_ID", "STATUS");

INSERT INTO "TB_FRED_SERIES"
    ("SERIES_CD","SERIES_NM","CATEGORY_CD","CNTRY_CD","FREQUENCY_CD","UNIT_NM","SEASONAL_ADJ_NM","COLLECT_CYCLE_CD","REFRESH_OVERLAP_DAY","TARGET_CD")
VALUES
