ON CONFLICT ("SERIES_CD") DO NOTHING;

COMMENT ON TABLE "TB_FRED_SERIES" IS '범용 FRED Series 기준정보';
COMMENT ON TABLE "TB_FRED_OBS" IS 'FRED Series 최신 유효 관측값';
COMMENT ON TABLE "TB_FRED_OBS_HIST" IS 'FRED 관측값 정정 이력';
COMMENT ON TABLE "TB_FRED_CLCT_JOB" IS 'FRED 기간 수집 상위 Job';
COMMENT ON TABLE "TB_FRED_CLCT_JOB_ITEM" IS 'FRED Series별 수집 Job Item';
